      try {
        const dashAbort = new AbortController();
        const dashTimeout = setTimeout(() => dashAbort.abort(), 15000);
        const opts = {signal: dashAbort.signal};
        // Get total task count and status-specific counts for accurate dashboard stats
        const taskData = await fetchJSON('/api/tasks?limit=1', opts);
        const runningData = await fetchJSON('/api/tasks?status=running&limit=1', opts);
        const pendingData = await fetchJSON('/api/tasks?status=pending&limit=1', opts);
        const [projData, chatData, fbData, appData, approvalData, audioData, costData] = await Promise.all([
          fetchJSON('/api/projects', opts),
          fetchJSON('/api/chats', opts),
          fetchJSON('/api/feedback', opts).catch(() => ({feedback: []})),
          fetchJSON('/api/apps', opts).catch(() => ({apps: []})),
          fetchJSON('/api/approval-requests', opts).catch(() => ({approval_requests: []})),
          fetchJSON('/api/audio', opts).catch(() => ({recordings: []})),
          fetchJSON('/api/stats/costs', opts).catch(() => ({daily: [], by_project: [], top_tasks: []}))
        ]);
        clearTimeout(dashTimeout);
        if (navGeneration !== gen) { showLoading(false); return; }
        const tasks = taskData.tasks || [];
        const projects = projData.projects || [];
        const chats = chatData.chats || [];
        const apps = appData.apps || [];
        const runningApps = apps.filter(a => (a.Status || a.status) === 'running');
        const runningTasks = runningData.tasks || [];
        const pendingTasks = pendingData.tasks || [];
        const activeProjects = projects.filter(p => p.status === 'active');
        const attentionItems = (approvalData.approval_requests || []).filter(a => a.status === 'requested');
        const totalCost = costData.total_all_time || tasks.reduce((s, t) => s + (t.cost_usd || 0), 0);
</parameter>
